CREATE TABLE IF NOT EXISTS om_sessions(id BIGINT AUTO_INCREMENT PRIMARY KEY, platform VARCHAR(20) NOT NULL, shop VARCHAR(100) NOT NULL, fulfillment_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Open', closed_by INT NULL, closed_at DATETIME NULL, UNIQUE(platform,shop,fulfillment_date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_uploads(id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(20) NOT NULL, platform VARCHAR(20) NOT NULL, shop VARCHAR(100) NOT NULL, filename VARCHAR(255), stored_path VARCHAR(255), file_hash CHAR(64), meta_json LONGTEXT NOT NULL, rows_json LONGTEXT NOT NULL, result_json LONGTEXT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Review', revision INT NOT NULL DEFAULT 1, created_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at DATETIME NULL, INDEX(platform,shop,file_hash), INDEX(status,kind)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_orders(id BIGINT AUTO_INCREMENT PRIMARY KEY, platform VARCHAR(20) NOT NULL, shop VARCHAR(100) NOT NULL, order_no VARCHAR(100) NOT NULL, created_order_at DATETIME NOT NULL, fulfillment_date DATE NOT NULL, session_id BIGINT NULL, registration_id BIGINT NULL, platform_status VARCHAR(40) NOT NULL DEFAULT 'To Ship', raw_status VARCHAR(150), posting VARCHAR(20) NOT NULL DEFAULT 'Not Posted', monitoring VARCHAR(40) NOT NULL DEFAULT 'Needs Follow-up', last_seen_at DATETIME NULL, status_changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, owner_id INT NOT NULL, followup_date DATE NULL, aftersales VARCHAR(30) NOT NULL DEFAULT '', aftersales_resolution VARCHAR(30) NOT NULL DEFAULT '', exception_text TEXT NULL, last_snapshot DATETIME NULL, revision INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(platform,shop,order_no), INDEX(fulfillment_date), INDEX(posting,platform_status), INDEX(owner_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_lines(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, line_key CHAR(64) NOT NULL, source_json LONGTEXT NOT NULL, components_json LONGTEXT NOT NULL, UNIQUE(order_id,line_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_reservations(order_id BIGINT NOT NULL, product_id INT NOT NULL, qty INT NOT NULL, PRIMARY KEY(order_id,product_id), INDEX(product_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_postings(order_id BIGINT NOT NULL, outflow_id BIGINT NOT NULL, PRIMARY KEY(order_id,outflow_id), UNIQUE(outflow_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NULL, upload_id BIGINT NULL, event_type VARCHAR(60) NOT NULL, details_json LONGTEXT NOT NULL, user_id INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(order_id), INDEX(upload_id), INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_reservation_events(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id INT NOT NULL, delta INT NOT NULL, event_type VARCHAR(50) NOT NULL, user_id INT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(product_id,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_mappings(mapping_key CHAR(64) PRIMARY KEY, platform VARCHAR(20) NOT NULL, shop VARCHAR(100) NOT NULL, source_json LONGTEXT NOT NULL, components_json LONGTEXT NOT NULL, saved_by INT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS om_alerts(alert_key VARCHAR(180) PRIMARY KEY, order_id BIGINT NULL, owner_id INT NULL, title VARCHAR(255) NOT NULL, resolved TINYINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(owner_id,resolved)) ENGINE=InnoDB;
